// Formula parsing and evaluation.
import { parseAddr, toAddr } from "./addr.mjs";

const REF = /^\$?[A-Za-z]{1,3}\$?[1-9]\d*$/;
const TOKEN = /\s*(?:(\d+\.?\d*(?:[eE][+-]?\d+)?|\.\d+(?:[eE][+-]?\d+)?)|"((?:[^"]|"")*)"|([A-Za-z_$][A-Za-z0-9_$]*)|(<>|<=|>=|[=<>&+\-*\/^(),:]))/y;

function tokenize(text) {
  const out = [];
  let pos = 0;
  while (true) {
    const rest = /\s*/y;
    rest.lastIndex = pos;
    rest.exec(text);
    pos = rest.lastIndex;
    if (pos >= text.length) break;
    TOKEN.lastIndex = pos;
    const m = TOKEN.exec(text);
    if (!m) throw new SyntaxError(`unexpected character '${text[pos]}' at ${pos}`);
    pos = TOKEN.lastIndex;
    if (m[1] !== undefined) out.push({ t: "num", v: Number(m[1]) });
    else if (m[2] !== undefined) out.push({ t: "str", v: m[2].replace(/""/g, '"') });
    else if (m[3] !== undefined) out.push({ t: "id", v: m[3] });
    else out.push({ t: "op", v: m[4] });
  }
  return out;
}

const normRef = (text) => {
  const a = parseAddr(text);
  return { col: a.col, row: a.row };
};

export function parseFormula(text) {
  const toks = tokenize(String(text));
  let i = 0;
  const peek = () => toks[i];
  const isOp = (v) => toks[i] && toks[i].t === "op" && toks[i].v === v;
  const expect = (v) => {
    if (!isOp(v)) throw new SyntaxError(`expected '${v}'`);
    i++;
  };

  function binary(next, ops) {
    let left = next();
    while (toks[i] && toks[i].t === "op" && ops.includes(toks[i].v)) {
      const op = toks[i++].v;
      left = { type: "bin", op, left, right: next() };
    }
    return left;
  }
  const comparison = () => binary(concat, ["=", "<>", "<", ">", "<=", ">="]);
  const concat = () => binary(additive, ["&"]);
  const additive = () => binary(term, ["+", "-"]);
  const term = () => binary(power, ["*", "/"]);
  const power = () => binary(unary, ["^"]);
  function unary() {
    if (isOp("-") || isOp("+")) {
      const op = toks[i++].v;
      return { type: "un", op, arg: unary() };
    }
    return primary();
  }
  function primary() {
    const tok = toks[i++];
    if (!tok) throw new SyntaxError("unexpected end of formula");
    if (tok.t === "num") return { type: "num", value: tok.v };
    if (tok.t === "str") return { type: "str", value: tok.v };
    if (tok.t === "op") {
      if (tok.v === "(") {
        const e = comparison();
        expect(")");
        return e;
      }
      throw new SyntaxError(`unexpected '${tok.v}'`);
    }
    const name = tok.v;
    if (isOp("(")) {
      i++;
      const args = [];
      if (!isOp(")")) {
        args.push(comparison());
        while (isOp(",")) {
          i++;
          args.push(comparison());
        }
      }
      expect(")");
      return { type: "call", name: name.toUpperCase(), args };
    }
    if (REF.test(name)) {
      const a = normRef(name);
      if (isOp(":")) {
        i++;
        const t2 = toks[i++];
        if (!t2 || t2.t !== "id" || !REF.test(t2.v)) throw new SyntaxError("bad range");
        const b = normRef(t2.v);
        return {
          type: "range",
          c1: Math.min(a.col, b.col), r1: Math.min(a.row, b.row),
          c2: Math.max(a.col, b.col), r2: Math.max(a.row, b.row),
        };
      }
      return { type: "ref", addr: toAddr(a.col, a.row) };
    }
    const up = name.toUpperCase();
    if (up === "TRUE") return { type: "bool", value: true };
    if (up === "FALSE") return { type: "bool", value: false };
    if (name.startsWith("$")) throw new SyntaxError(`bad reference ${name}`);
    return { type: "name", name };
  }

  if (!toks.length) throw new SyntaxError("empty formula");
  const ast = comparison();
  if (i < toks.length) throw new SyntaxError(`unexpected '${toks[i].v}'`);
  return ast;
}

function* rangeAddrs(n) {
  for (let r = n.r1; r <= n.r2; r++) for (let c = n.c1; c <= n.c2; c++) yield toAddr(c, r);
}

export function refsOf(ast) {
  const seen = new Set();
  const walk = (n) => {
    switch (n.type) {
      case "ref": seen.add(n.addr); break;
      case "range": for (const a of rangeAddrs(n)) seen.add(a); break;
      case "bin": walk(n.left); walk(n.right); break;
      case "un": walk(n.arg); break;
      case "call": n.args.forEach(walk); break;
    }
  };
  walk(ast);
  return [...seen];
}

const isErr = (v) => typeof v === "string" && v.startsWith("#");

function toNum(v) {
  if (isErr(v)) return v;
  if (v === null || v === undefined) return 0;
  if (typeof v === "number") return v;
  if (typeof v === "boolean") return v ? 1 : 0;
  const s = v.trim();
  if (s === "") return "#VALUE!";
  const n = Number(s);
  return Number.isNaN(n) ? "#VALUE!" : n;
}

function toText(v) {
  if (v === null || v === undefined) return "";
  if (typeof v === "boolean") return v ? "TRUE" : "FALSE";
  return String(v);
}

function toBool(v) {
  if (isErr(v)) return v;
  if (v === null || v === undefined) return false;
  if (typeof v === "boolean") return v;
  if (typeof v === "number") return v !== 0;
  const u = v.toUpperCase();
  if (u === "TRUE") return true;
  if (u === "FALSE") return false;
  return "#VALUE!";
}

const rank = (v) => (typeof v === "number" ? 0 : typeof v === "string" ? 1 : 2);

function compare(a, b) {
  if (a === null) a = b === null ? 0 : typeof b === "number" ? 0 : typeof b === "string" ? "" : false;
  if (b === null) b = typeof a === "number" ? 0 : typeof a === "string" ? "" : false;
  const ra = rank(a), rb = rank(b);
  if (ra !== rb) return ra - rb;
  if (ra === 1) { a = a.toLowerCase(); b = b.toLowerCase(); }
  return a < b ? -1 : a > b ? 1 : 0;
}

function shift(x, k) {
  const [m, e] = x.toExponential().split("e");
  return Number(`${m}e${Number(e) + k}`);
}

function round(x, d) {
  d = Math.trunc(d);
  const abs = Math.abs(x);
  if (abs === 0) return 0;
  const r = Math.round(shift(abs, d));
  return Math.sign(x) * shift(r, -d);
}

const finite = (n) => (Number.isFinite(n) ? n : "#NUM!");

export function evaluate(ast, lookup) {
  const val = (n) => {
    switch (n.type) {
      case "num": case "str": case "bool": return n.value;
      case "name": return "#NAME?";
      case "range": return "#VALUE!";
      case "ref": return lookup(n.addr) ?? null;
      case "un": {
        const x = toNum(val(n.arg));
        if (typeof x === "string") return x;
        return n.op === "-" ? finite(-x) || 0 : x;
      }
      case "bin": return binop(n);
      case "call": return call(n);
    }
  };

  function binop(n) {
    const l = val(n.left);
    if (isErr(l)) return l;
    const r = val(n.right);
    if (isErr(r)) return r;
    const op = n.op;
    if (op === "&") return toText(l) + toText(r);
    if (["=", "<>", "<", ">", "<=", ">="].includes(op)) {
      const c = compare(l, r);
      switch (op) {
        case "=": return c === 0;
        case "<>": return c !== 0;
        case "<": return c < 0;
        case ">": return c > 0;
        case "<=": return c <= 0;
        default: return c >= 0;
      }
    }
    const x = toNum(l);
    if (isErr(x)) return x;
    const y = toNum(r);
    if (isErr(y)) return y;
    switch (op) {
      case "+": return finite(x + y);
      case "-": return finite(x - y);
      case "*": return finite(x * y);
      case "/": return y === 0 ? "#DIV/0!" : finite(x / y);
      default: return finite(x ** y);
    }
  }

  // Values of a range argument, row by row.
  const rangeVals = (n) => [...rangeAddrs(n)].map((a) => lookup(a) ?? null);

  const arity = (n, min, max) => n.args.length >= min && n.args.length <= max;

  function numericArgs(n, count) {
    const nums = [];
    for (const a of n.args) {
      if (a.type === "range") {
        for (const v of rangeVals(a)) {
          if (isErr(v)) { if (count) continue; return v; }
          if (typeof v === "number") nums.push(v);
        }
      } else {
        const v = val(a);
        if (count) { if (typeof v === "number") nums.push(v); continue; }
        const x = toNum(v);
        if (typeof x === "string") return x;
        nums.push(x);
      }
    }
    return nums;
  }

  function boolArgs(n) {
    const out = [];
    for (const a of n.args) {
      if (a.type === "range") {
        for (const v of rangeVals(a)) {
          if (isErr(v)) return v;
          if (typeof v === "number") out.push(v !== 0);
          else if (typeof v === "boolean") out.push(v);
        }
      } else {
        const b = toBool(val(a));
        if (typeof b === "string") return b;
        out.push(b);
      }
    }
    return out;
  }

  // Evaluates single-value args in order, returning the first error or the list.
  function scalars(n) {
    const out = [];
    for (const a of n.args) {
      const v = val(a);
      if (isErr(v)) return v;
      out.push(v);
    }
    return out;
  }

  function call(n) {
    const name = n.name;
    switch (name) {
      case "SUM": case "AVERAGE": case "MIN": case "MAX": case "COUNT": {
        const nums = numericArgs(n, name === "COUNT");
        if (typeof nums === "string") return nums;
        if (name === "COUNT") return nums.length;
        if (name === "SUM") return finite(nums.reduce((s, x) => s + x, 0));
        if (name === "AVERAGE") return nums.length ? finite(nums.reduce((s, x) => s + x, 0) / nums.length) : "#DIV/0!";
        if (!nums.length) return 0;
        return name === "MIN" ? Math.min(...nums) : Math.max(...nums);
      }
      case "IF": {
        if (!arity(n, 2, 3)) return "#VALUE!";
        if (n.args.some((a) => a.type === "range" && a !== n.args[0] && false)) return "#VALUE!";
        const c = toBool(val(n.args[0]));
        if (typeof c === "string") return c;
        if (c) return val(n.args[1]);
        return n.args.length > 2 ? val(n.args[2]) : false;
      }
      case "AND": case "OR": {
        if (!arity(n, 1, Infinity)) return "#VALUE!";
        const bs = boolArgs(n);
        if (typeof bs === "string") return bs;
        return name === "AND" ? bs.every(Boolean) : bs.some(Boolean);
      }
      case "NOT": {
        if (!arity(n, 1, 1)) return "#VALUE!";
        const b = toBool(val(n.args[0]));
        return typeof b === "string" ? b : !b;
      }
      case "ROUND": {
        if (!arity(n, 2, 2)) return "#VALUE!";
        const s = scalars(n);
        if (typeof s === "string") return s;
        const x = toNum(s[0]);
        if (typeof x === "string") return x;
        const d = toNum(s[1]);
        if (typeof d === "string") return d;
        return finite(round(x, d));
      }
      case "ABS": {
        if (!arity(n, 1, 1)) return "#VALUE!";
        const x = toNum(val(n.args[0]));
        return typeof x === "string" ? x : Math.abs(x);
      }
      case "LEN": case "UPPER": case "LOWER": {
        if (!arity(n, 1, 1)) return "#VALUE!";
        const v = val(n.args[0]);
        if (isErr(v)) return v;
        const s = toText(v);
        return name === "LEN" ? s.length : name === "UPPER" ? s.toUpperCase() : s.toLowerCase();
      }
      case "CONCAT": {
        let out = "";
        for (const a of n.args) {
          const vs = a.type === "range" ? rangeVals(a) : [val(a)];
          for (const v of vs) {
            if (isErr(v)) return v;
            out += toText(v);
          }
        }
        return out;
      }
      default: return "#NAME?";
    }
  }

  return val(ast);
}
