// CSV import/export.
import { createSheet, setCell, getCell, cellAddrs } from "./sheet.mjs";
import { parseAddr, toAddr } from "./addr.mjs";

const valueText = (v) => (v === null || v === undefined ? "" : typeof v === "boolean" ? (v ? "TRUE" : "FALSE") : String(v));

function quote(s) {
  return /[,"\n\r]/.test(s) || s.startsWith(" ") || s.endsWith(" ") ? `"${s.replace(/"/g, '""')}"` : s;
}

export function toCSV(sheet, values) {
  const addrs = cellAddrs(sheet);
  if (!addrs.length) return "";
  let cols = 0, rows = 0;
  for (const a of addrs) {
    const p = parseAddr(a);
    cols = Math.max(cols, p.col + 1);
    rows = Math.max(rows, p.row + 1);
  }
  let out = "";
  for (let r = 0; r < rows; r++) {
    const fields = [];
    for (let c = 0; c < cols; c++) {
      const addr = toAddr(c, r);
      fields.push(quote(values ? valueText(values.get(addr)) : getCell(sheet, addr)));
    }
    out += fields.join(",") + "\n";
  }
  return out;
}

function detectDelimiter(text) {
  const counts = { ",": 0, ";": 0, "\t": 0 };
  let inQ = false, start = true;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (inQ) {
      if (ch === '"') {
        if (text[i + 1] === '"') i++;
        else inQ = false;
      }
      continue;
    }
    if (ch === "\n" || ch === "\r") break;
    if (ch === '"' && start) { inQ = true; start = false; continue; }
    start = false;
    if (ch in counts) { counts[ch]++; start = true; }
  }
  let best = ",";
  for (const d of [";", "\t"]) if (counts[d] > counts[best]) best = d;
  return best;
}

export function fromCSV(text, options = {}) {
  const delim = options.delimiter ?? detectDelimiter(text);
  const rows = [];
  let row = [], field = "", started = false;
  let i = 0;
  const endField = () => { row.push(field); field = ""; started = false; };
  const endRow = () => { endField(); rows.push(row); row = []; };
  while (i < text.length) {
    const ch = text[i];
    if (ch === '"' && !started) {
      const begin = i;
      started = true;
      i++;
      let closed = false;
      while (i < text.length) {
        if (text[i] === '"') {
          if (text[i + 1] === '"') { field += '"'; i += 2; continue; }
          closed = true; i++;
          break;
        }
        field += text[i++];
      }
      if (!closed) {
        let line = 1;
        for (let k = 0; k < begin; k++) if (text[k] === "\n") line++;
        throw new Error(`unclosed quote at line ${line}`);
      }
      continue;
    }
    if (ch === delim) { endField(); i++; continue; }
    if (ch === "\n") { endRow(); i++; continue; }
    if (ch === "\r" && text[i + 1] === "\n") { endRow(); i += 2; continue; }
    field += ch;
    started = true;
    i++;
  }
  if (started || field !== "" || row.length) endRow();

  const sheet = createSheet();
  rows.forEach((r, ri) => r.forEach((f, ci) => {
    if (f === "") return;
    if (f.startsWith("=") && !options.formulas) f = "'" + f;
    setCell(sheet, toAddr(ci, ri), f);
  }));
  return sheet;
}
