// Recalculation: cell values, whole-sheet computation and dependency queries.
import { parseFormula, refsOf, evaluate } from "./formula.mjs";
import { parseAddr, compareAddr } from "./addr.mjs";

const NUMBER = /^[+-]?(\d+\.?\d*|\.\d+)(e[+-]?\d+)?$/i;

// The value of a non-formula cell's raw text.
export function valueOf(raw) {
  if (raw === "" || raw == null) return null;
  const t = raw.trim();
  if (NUMBER.test(t) && Number.isFinite(Number(t))) return Number(t);
  const u = raw.toUpperCase();
  if (u === "TRUE") return true;
  if (u === "FALSE") return false;
  if (raw[0] === "'") return raw.slice(1);
  return raw;
}

// Parses every formula; returns { asts, refs } where refs maps a formula cell to the formula cells it reads.
function graph(sheet) {
  const asts = new Map(), refs = new Map();
  for (const [addr, raw] of sheet.cells) {
    if (raw[0] !== "=") continue;
    let ast = null;
    try { ast = parseFormula(raw.slice(1)); } catch { ast = null; }
    asts.set(addr, ast);
  }
  for (const [addr, ast] of asts) {
    const list = [];
    if (ast) for (const r of refsOf(ast)) if (asts.has(r)) list.push(r);
    refs.set(addr, list);
  }
  return { asts, refs };
}

// Iterative Tarjan. Returns SCCs, each after every SCC it reads from.
function components(refs) {
  const index = new Map(), low = new Map(), on = new Set(), stack = [], out = [];
  let n = 0;
  for (const root of refs.keys()) {
    if (index.has(root)) continue;
    const work = [[root, 0]];
    index.set(root, n); low.set(root, n++); stack.push(root); on.add(root);
    while (work.length) {
      const frame = work[work.length - 1];
      const [v, i] = frame;
      const next = refs.get(v);
      if (i < next.length) {
        frame[1]++;
        const w = next[i];
        if (!index.has(w)) {
          index.set(w, n); low.set(w, n++); stack.push(w); on.add(w);
          work.push([w, 0]);
        } else if (on.has(w)) low.set(v, Math.min(low.get(v), index.get(w)));
      } else {
        work.pop();
        if (work.length) {
          const p = work[work.length - 1][0];
          low.set(p, Math.min(low.get(p), low.get(v)));
        }
        if (low.get(v) === index.get(v)) {
          const comp = [];
          let w;
          do { w = stack.pop(); on.delete(w); comp.push(w); } while (w !== v);
          out.push(comp);
        }
      }
    }
  }
  return out;
}

const cyclic = (comp, refs) => comp.length > 1 || refs.get(comp[0]).includes(comp[0]);

// A Map from every non-empty cell's address to its value.
export function computeAll(sheet) {
  const { asts, refs } = graph(sheet);
  const values = new Map();
  const lookup = (a) => values.get(a) ?? null;
  for (const comp of components(refs)) {
    if (cyclic(comp, refs)) { for (const a of comp) values.set(a, "#CYCLE!"); continue; }
    const a = comp[0], ast = asts.get(a);
    values.set(a, ast ? evaluate(ast, lookup) : "#ERROR!");
  }
  for (const [addr, raw] of sheet.cells) if (raw[0] !== "=") values.set(addr, valueOf(raw));
  // Map order: by sheet insertion order
  return new Map([...sheet.cells.keys()].map((a) => [a, values.get(a)]));
}

// Formula cells reading addr directly or indirectly, each after the cells it reads; ties by row, then column.
export function dependents(sheet, addr) {
  const p = parseAddr(addr);
  const start = [...sheet.cells.keys()].find((a) => { const q = parseAddr(a); return q.row === p.row && q.col === p.col; }) ?? addr;
  const { refs } = graph(sheet);
  const bad = new Set();
  for (const comp of components(refs)) if (cyclic(comp, refs)) for (const a of comp) bad.add(a);

  const readers = new Map();
  for (const [a, list] of refs) for (const r of list) (readers.get(r) ?? readers.set(r, []).get(r)).push(a);
  // Cells reading `addr` may name it without being a formula cell, so scan references directly.
  const { asts } = graph(sheet);
  const direct = [];
  for (const [a, ast] of asts) if (ast && a !== start && refsOf(ast).includes(start)) direct.push(a);

  const seen = new Set(direct), queue = [...direct];
  while (queue.length) {
    const v = queue.pop();
    for (const w of readers.get(v) ?? []) if (!seen.has(w) && w !== start) { seen.add(w); queue.push(w); }
  }
  const set = [...seen].filter((a) => !bad.has(a));
  const inSet = new Set(set);
  const waiting = new Map(), out = [];
  const subs = new Map();
