// Table operations: sorting a range of rows and pivoting computed values.
import { valueOf } from "./recalc.mjs";
import { parseAddr, toAddr, colIndex, colName } from "./addr.mjs";
import { getCell, setCell } from "./sheet.mjs";

function parseRange(range) {
  const [a, b] = range.split(":");
  const p = parseAddr(a), q = parseAddr(b ?? a);
  return { c0: Math.min(p.col, q.col), c1: Math.max(p.col, q.col), r0: Math.min(p.row, q.row), r1: Math.max(p.row, q.row) };
}

const rank = (v) => (typeof v === "number" ? 0 : typeof v === "boolean" ? 2 : 1);

// Numbers, then strings case-insensitively, then booleans (false first).
function compareValues(a, b) {
  const ra = rank(a), rb = rank(b);
  if (ra !== rb) return ra - rb;
  if (ra === 1) { const x = a.toLowerCase(), y = b.toLowerCase(); return x < y ? -1 : x > y ? 1 : 0; }
  return a < b ? -1 : a > b ? 1 : 0;
}

export function sortRange(sheet, range, keys, options = {}) {
  const { c0, c1, r0, r1 } = parseRange(range);
  const first = options.header ? r0 + 1 : r0;
  const rows = [];
  for (let r = first; r <= r1; r++) {
    const raws = [];
    for (let c = c0; c <= c1; c++) raws.push(getCell(sheet, toAddr(c, r)));
    rows.push(raws);
  }
  const cols = keys.map((k) => ({ i: colIndex(k.col) - c0, desc: !!k.desc }));
  const vals = new Map(rows.map((row) => [row, cols.map((k) => valueOf(row[k.i] ?? ""))]));
  rows.sort((x, y) => {
    for (let k = 0; k < cols.length; k++) {
      const a = vals.get(x)[k], b = vals.get(y)[k];
      if (a === null || b === null) {
        if (a === b) continue;
        return a === null ? 1 : -1;
      }
      const d = compareValues(a, b);
      if (d) return cols[k].desc ? -d : d;
    }
    return 0;
  });
  rows.forEach((raws, n) => raws.forEach((raw, j) => setCell(sheet, toAddr(c0 + j, first + n), raw)));
}

export function pivot(values, range, { rows, value, agg }) {
  const { c0, c1, r0, r1 } = parseRange(range);
  const find = (name) => {
    for (let c = c0; c <= c1; c++) if (String(values.get(toAddr(c, r0)) ?? "") === String(name)) return c;
    throw new Error(`no such column: ${name}`);
  };
  const kc = find(rows), vc = find(value);
  const groups = new Map();
  for (let r = r0 + 1; r <= r1; r++) {
    const k = values.get(toAddr(kc, r)) ?? null;
    const key = k === null ? "(blank)" : k;
    const g = groups.get(key) ?? groups.set(key, { key, blank: k === null, items: [] }).get(key);
    g.items.push(values.get(toAddr(vc, r)) ?? null);
  }
  const out = [...groups.values()].map((g) => {
    const nums = g.items.filter((v) => typeof v === "number");
    let result;
    if (agg === "count") result = g.items.filter((v) => v !== null).length;
    else if (agg === "sum") result = nums.reduce((s, v) => s + v, 0);
    else if (!nums.length) result = null;
    else if (agg === "avg") result = nums.reduce((s, v) => s + v, 0) / nums.length;
    else if (agg === "min") result = nums.reduce((m, v) => Math.min(m, v));
    else if (agg === "max") result = nums.reduce((m, v) => Math.max(m, v));
    else throw new Error(`unknown aggregate: ${agg}`);
    return { g, key: g.key, value: result };
  });
  out.sort((x, y) => (x.g.blank - y.g.blank) || (x.g.blank ? 0 : compareValues(x.key, y.key)));
  return out.map(({ key, value }) => ({ key, value }));
}
