// Inserting and deleting rows and columns, rewriting formula references to follow the cells.
import { parseAddr, toAddr, colName, colIndex } from "./addr.mjs";

const REF = /\$?[A-Za-z]+\$?\d+/y;
const isWord = (c) => c !== undefined && /[A-Za-z0-9_.]/.test(c);

// Maps one coordinate; returns null when the cell is deleted.
function mapPoint(p, op) {
  if (op.insert) return p >= op.at ? p + op.count : p;
  if (p < op.at) return p;
  return p >= op.at + op.count ? p - op.count : null;
}

// Maps a range's [s, e] coordinates; returns null when all of it is deleted.
function mapRange(s, e, op) {
  if (op.insert) return [s >= op.at ? s + op.count : s, e >= op.at ? e + op.count : e];
  const { at, count } = op;
  const lo = s < at ? s : s >= at + count ? s - count : at;
  const hi = e < at ? e : e >= at + count ? e - count : at - 1;
  return hi < lo ? null : [lo, hi];
}

const shift = (a, op) => {
  const key = op.axis;
  const v = mapPoint(a[key], op);
  return v == null ? null : { ...a, [key]: v };
};

const show = (a) => `${a.colAbs ? "$" : ""}${colName(a.col)}${a.rowAbs ? "$" : ""}${a.row + 1}`;

function rewrite(formula, op) {
  let out = "", i = 0;
  const readRef = (pos) => {
    REF.lastIndex = pos;
    const m = REF.exec(formula);
    if (!m) return null;
    const end = pos + m[0].length;
    if (isWord(formula[pos - 1]) || isWord(formula[end]) || formula[end] === "(") return null;
    try { return { text: m[0], end, a: parseAddr(m[0]) }; } catch { return null; }
  };
  while (i < formula.length) {
    const c = formula[i];
    if (c === '"') {
      let j = i + 1;
      while (j < formula.length && !(formula[j] === '"' && formula[j + 1] !== '"')) j += formula[j] === '"' ? 2 : 1;
      out += formula.slice(i, j + 1); i = j + 1;
      continue;
    }
    const r = /[$A-Za-z]/.test(c) ? readRef(i) : null;
    if (!r) { out += c; i++; continue; }
    const r2 = formula[r.end] === ":" ? readRef(r.end + 1) : null;
    if (r2) {
      const k = op.axis;
      const [x, y] = [r.a[k], r2.a[k]];
      const m = mapRange(Math.min(x, y), Math.max(x, y), op);
      if (!m) out += "#REF!";
      else {
        const swap = x > y;
        out += show({ ...r.a, [k]: m[swap ? 1 : 0] }) + ":" + show({ ...r2.a, [k]: m[swap ? 0 : 1] });
      }
      i = r2.end;
    } else {
      const a = shift(r.a, op);
      out += a ? show(a) : "#REF!";
      i = r.end;
    }
  }
  return out;
}

function apply(sheet, op) {
  const next = new Map();
  for (const [addr, raw] of sheet.cells) {
    const a = parseAddr(addr);
    const v = mapPoint(a[op.axis], op);
    if (v == null) continue;
    const na = { ...a, [op.axis]: v };
    next.set(toAddr(na.col, na.row), raw.startsWith("=") ? rewrite(raw, op) : raw);
  }
  sheet.cells = next;
}

const rowOp = (insert) => (sheet, at, count = 1) =>
  apply(sheet, { axis: "row", insert, at: at - 1, count });
const colOp = (insert) => (sheet, at, count = 1) =>
  apply(sheet, { axis: "col", insert, at: colIndex(at), count });

export const insertRows = rowOp(true);
export const deleteRows = rowOp(false);
export const insertCols = colOp(true);
export const deleteCols = colOp(false);
